static BOOL PVXString(id v,NSUInteger n){return [v isKindOfClass:NSString.class]&&[v length]<=n;}
static NSURL *PVXImageURL(id v){if(!PVXString(v,16384))return nil;NSURL *u=[NSURL URLWithString:v];return u.host.length&&([u.scheme.lowercaseString isEqual:@"https"]||[u.scheme.lowercaseString isEqual:@"http"])?u:nil;}
static NSArray *PVXMatching(NSArray *cookies,NSURL *url){NSMutableArray *out=[NSMutableArray array];NSString *host=url.host.lowercaseString,*path=url.path.length?url.path:@"/";for(NSHTTPCookie *c in cookies){NSString *domain=c.domain.lowercaseString;BOOL sub=[domain hasPrefix:@"."];if(sub)domain=[domain substringFromIndex:1];BOOL match=[host isEqual:domain]||(sub&&[host hasSuffix:[@"." stringByAppendingString:domain]]);NSString *cp=c.path.length?c.path:@"/";BOOL pm=[path isEqual:cp]||([path hasPrefix:cp]&&([cp hasSuffix:@"/"]||(path.length>cp.length&&[path characterAtIndex:cp.length]=='/')));if(match&&pm&&(!c.secure||[url.scheme.lowercaseString isEqual:@"https"])&&(!c.expiresDate||c.expiresDate.timeIntervalSinceNow>0))[out addObject:c];}return out;}
static NSDictionary *PVXCookieRecord(NSHTTPCookie *c){NSMutableDictionary *p=[@{NSHTTPCookieName:c.name,NSHTTPCookieValue:c.value,NSHTTPCookieDomain:c.domain,NSHTTPCookiePath:c.path.length?c.path:@"/"} mutableCopy];if(c.secure)p[NSHTTPCookieSecure]=@"TRUE";if(c.expiresDate)p[NSHTTPCookieExpires]=c.expiresDate;return p;}
static NSDictionary *PVXHeaders(NSArray *cookies,NSURL *url,NSString *referer,NSString *ua){NSMutableDictionary *h=[NSMutableDictionary dictionary];if(PVXString(ua,16384)&&ua.length&&[ua rangeOfCharacterFromSet:NSCharacterSet.newlineCharacterSet].location==NSNotFound)h[@"User-Agent"]=ua;NSURLComponents *r=[NSURLComponents componentsWithString:referer];r.user=nil;r.password=nil;r.fragment=nil;if(r.URL&&(![r.scheme.lowercaseString isEqual:@"https"]||[url.scheme.lowercaseString isEqual:@"https"]))h[@"Referer"]=r.string;NSArray *cs=PVXMatching(cookies,url);if(cs.count)[h addEntriesFromDictionary:[NSHTTPCookie requestHeaderFieldsWithCookies:cs]];return h;}
@implementation PVXMediaBridge
+ (instancetype)shared{static id v;static dispatch_once_t once;dispatch_once(&once,^{v=[self new];});return v;}
- (instancetype)init{if((self=[super init])){_frames=[NSMapTable weakToStrongObjectsMapTable];_script=[NSString stringWithContentsOfFile:PVXResourcePath(@"MediaCollector.js") encoding:NSUTF8StringEncoding error:nil];}return self;}
- (void)configure:(WKWebViewConfiguration*)config{if(!config||!self.script.length)return;WKUserContentController *uc=config.userContentController;if(objc_getAssociatedObject(uc,&PVXConfigKey))return;id b=PVXBrowser();WKContentWorld *world=PVXGet(b,@"world");if(![world isKindOfClass:WKContentWorld.class])world=WKContentWorld.defaultClientWorld;[uc addScriptMessageHandler:self contentWorld:world name:PVXBridgeName];[uc addUserScript:[[WKUserScript alloc] initWithSource:self.script injectionTime:WKUserScriptInjectionTimeAtDocumentStart forMainFrameOnly:NO inContentWorld:world]];objc_setAssociatedObject(uc,&PVXConfigKey,@YES,OBJC_ASSOCIATION_RETAIN_NONATOMIC);}
- (void)userContentController:(WKUserContentController*)uc didReceiveScriptMessage:(WKScriptMessage*)message{if(![message.name isEqual:PVXBridgeName]||![message.body isKindOfClass:NSDictionary.class]||!message.webView)return;NSDictionary *m=message.body;NSArray *raw=m[@"images"];if(![m[@"version"] isEqual:@1]||!PVXString(m[@"documentID"],128)||![raw isKindOfClass:NSArray.class]||raw.count>300||!PVXString(m[@"page"],16384))return;NSMutableArray *images=[NSMutableArray array];for(id row in raw){if(![row isKindOfClass:NSDictionary.class]||!PVXImageURL(row[@"url"]))continue;NSMutableDictionary *c=[NSMutableDictionary dictionary];c[@"url"]=row[@"url"];c[@"title"]=PVXString(row[@"title"],180)?row[@"title"]:@"图片";for(NSString *k in @[@"width",@"height"]){id n=row[k];c[k]=[n isKindOfClass:NSNumber.class]?@(MIN(100000,MAX(0,[n integerValue]))):@0;}c[@"page"]=m[@"page"];[images addObject:c];}
 NSMutableDictionary *map=[self.frames objectForKey:message.webView];if(!map){map=[NSMutableDictionary dictionary];[self.frames setObject:map forKey:message.webView];}NSString *owner=message.webView.URL.absoluteString?:@"";for(NSString *k in [map.allKeys copy]){NSDictionary *old=map[k];if(![old[@"owner"] isEqual:owner]||([old[@"frameURL"] isEqual:m[@"page"]]&&![k isEqual:m[@"documentID"]]))[map removeObjectForKey:k];}if(map.count>=32&& !map[m[@"documentID"]])[map removeObjectForKey:map.allKeys.firstObject];
 NSMutableDictionary *snapshot=[@{@"images":images,@"owner":owner,@"frameURL":m[@"page"],@"at":@(NSDate.date.timeIntervalSince1970),@"frameInfo":message.frameInfo} mutableCopy];NSDictionary *a=m[@"active"];if([a isKindOfClass:NSDictionary.class]&&(PVXImageURL(a[@"url"])||[a[@"blob"] isEqual:@YES])){NSMutableDictionary *active=[a mutableCopy];active[@"page"]=owner;active[@"framePage"]=m[@"page"];active[@"receivedAt"]=snapshot[@"at"];snapshot[@"active"]=active;}map[m[@"documentID"]]=snapshot;[[NSNotificationCenter defaultCenter] postNotificationName:@"PVXMediaChanged" object:message.webView];}
- (NSArray*)images{WKWebView *w=PVXCurrentWebView();NSString *owner=w.URL.absoluteString;NSMutableArray *rows=[NSMutableArray array];NSMutableSet *seen=[NSMutableSet set];for(NSDictionary *s in [[self.frames objectForKey:w] allValues]){if(![s[@"owner"] isEqual:owner])continue;for(NSDictionary *image in s[@"images"]){if(![seen containsObject:image[@"url"]]){[seen addObject:image[@"url"]];[rows addObject:image];if(rows.count>=600)return rows;}}}return rows;}
- (NSDictionary*)active{WKWebView *w=PVXCurrentWebView();NSDictionary *best=nil;for(NSDictionary *s in [[self.frames objectForKey:w] allValues]){if(![s[@"owner"] isEqual:w.URL.absoluteString])continue;NSDictionary *a=s[@"active"];if(!a)continue;BOOL foreground=[a[@"fullscreen"] boolValue]||[a[@"pip"] boolValue];BOOL bestForeground=[best[@"fullscreen"] boolValue]||[best[@"pip"] boolValue];if(!best||(foreground&&!bestForeground)||(foreground==bestForeground&&[a[@"at"] doubleValue]>[best[@"at"] doubleValue]))best=a;}return best;}
- (void)refresh{WKWebView *w=PVXCurrentWebView();if(!w)return;id b=PVXBrowser();WKContentWorld *world=PVXGet(b,@"world");if(![world isKindOfClass:WKContentWorld.class])world=WKContentWorld.defaultClientWorld;NSString *code=self.script;[w evaluateJavaScript:code inFrame:nil inContentWorld:world completionHandler:nil];for(NSDictionary *snapshot in [[self.frames objectForKey:w] allValues]){WKFrameInfo *frame=snapshot[@"frameInfo"];if(frame&&!frame.isMainFrame)[w evaluateJavaScript:code inFrame:frame inContentWorld:world completionHandler:nil];}}
@end
NSDictionary *PVXActiveVideo(void){return [[PVXMediaBridge shared] active];}

@interface PVXThumbnail : NSObject<NSURLSessionDataDelegate>
@property(nonatomic,strong)NSMutableData *data;
@property(nonatomic,strong)NSURLSession *session;
@property(nonatomic,copy)void(^done)(UIImage*);
@property(nonatomic,copy)NSArray *cookies;
@property(nonatomic,copy)NSString *referer;
@property(nonatomic,copy)NSString *ua;
- (instancetype)initWithURL:(NSURL*)url cookies:(NSArray*)cookies referer:(NSString*)referer ua:(NSString*)ua done:(void(^)(UIImage*))done;
@end
@implementation PVXThumbnail
- (instancetype)initWithURL:(NSURL*)url cookies:(NSArray*)cookies referer:(NSString*)referer ua:(NSString*)ua done:(void(^)(UIImage*))done{if((self=[super init])){_data=[NSMutableData data];_cookies=[cookies copy];_referer=[referer copy];_ua=[ua copy];_done=[done copy];NSURLSessionConfiguration *cfg=NSURLSessionConfiguration.ephemeralSessionConfiguration;cfg.HTTPCookieStorage=nil;cfg.HTTPShouldSetCookies=NO;cfg.timeoutIntervalForRequest=15;cfg.timeoutIntervalForResource=25;NSOperationQueue *q=[NSOperationQueue new];q.maxConcurrentOperationCount=1;_session=[NSURLSession sessionWithConfiguration:cfg delegate:self delegateQueue:q];NSMutableURLRequest *r=[NSMutableURLRequest requestWithURL:url];r.allHTTPHeaderFields=PVXHeaders(cookies,url,referer,ua);[[_session dataTaskWithRequest:r] resume];}return self;}
- (void)URLSession:(NSURLSession*)s dataTask:(NSURLSessionDataTask*)task didReceiveResponse:(NSURLResponse*)r completionHandler:(void(^)(NSURLSessionResponseDisposition))completion{BOOL ok=[r isKindOfClass:NSHTTPURLResponse.class]&&((NSHTTPURLResponse*)r).statusCode==200&&r.expectedContentLength<=2*1024*1024;completion(ok?NSURLSessionResponseAllow:NSURLSessionResponseCancel);}
- (void)URLSession:(NSURLSession*)s dataTask:(NSURLSessionDataTask*)task didReceiveData:(NSData*)d{if(self.data.length+d.length>2*1024*1024){[task cancel];return;}[self.data appendData:d];}
- (void)URLSession:(NSURLSession*)s task:(NSURLSessionTask*)task willPerformHTTPRedirection:(NSHTTPURLResponse*)response newRequest:(NSURLRequest*)request completionHandler:(void(^)(NSURLRequest*))completion{NSURL *u=PVXImageURL(request.URL.absoluteString);if(!u||([response.URL.scheme.lowercaseString isEqual:@"https"]&&![u.scheme.lowercaseString isEqual:@"https"])){completion(nil);return;}NSMutableURLRequest *r=[request mutableCopy];r.allHTTPHeaderFields=PVXHeaders(self.cookies,u,self.referer,self.ua);completion(r);}
- (void)URLSession:(NSURLSession*)s task:(NSURLSessionTask*)task didCompleteWithError:(NSError*)error{UIImage *image=nil;if(!error&&self.data.length){CGImageSourceRef source=CGImageSourceCreateWithData((__bridge CFDataRef)self.data,NULL);if(source){NSDictionary *opts=@{(__bridge NSString*)kCGImageSourceCreateThumbnailFromImageAlways:@YES,(__bridge NSString*)kCGImageSourceCreateThumbnailWithTransform:@YES,(__bridge NSString*)kCGImageSourceThumbnailMaxPixelSize:@144};CGImageRef cg=CGImageSourceCreateThumbnailAtIndex(source,0,(__bridge CFDictionaryRef)opts);if(cg){image=[UIImage imageWithCGImage:cg];CGImageRelease(cg);}CFRelease(source);}}void(^done)(UIImage*)=self.done;self.done=nil;self.data=nil;[s finishTasksAndInvalidate];self.session=nil;dispatch_async(dispatch_get_main_queue(),^{if(done)done(image);});}
@end
@interface PVXImageGallery : UITableViewController
@property(nonatomic,copy)NSArray *rows;
@property(nonatomic,copy)NSArray *tasks;
@property(nonatomic,copy)NSArray *cookies;
@property(nonatomic,copy)NSString *ua;
@property(nonatomic,strong)NSCache *thumbs;
@property(nonatomic,strong)NSMutableSet *loading;
@property(nonatomic,strong)NSMutableArray *thumbJobs;
@property(nonatomic,strong)NSMutableSet *selectedURLs;
@property(nonatomic,strong)NSMutableSet *submitting;
@property(nonatomic,strong)NSTimer *timer;
@property(nonatomic,strong)UIBarButtonItem *downloadButton;
@end
static BOOL PVXWriteRequest(NSDictionary *request,NSError **error){NSString *root=PVXStateRoot();if(!root.length)return NO;NSString *dir=[root stringByAppendingPathComponent:@"image-inbox"];NSFileManager *fm=NSFileManager.defaultManager;if(![fm createDirectoryAtPath:dir withIntermediateDirectories:YES attributes:@{NSFilePosixPermissions:@0700} error:error])return NO;NSData *d=[NSPropertyListSerialization dataWithPropertyList:request format:NSPropertyListBinaryFormat_v1_0 options:0 error:error];NSString *file=[dir stringByAppendingPathComponent:[request[@"id"] stringByAppendingPathExtension:@"plist"]];if(!d||![d writeToFile:file options:NSDataWritingAtomic error:error])return NO;chmod(file.fileSystemRepresentation,0600);notify_post("com.crctdd.pyvideo.plus.images.queue");return YES;}
@implementation PVXImageGallery
- (void)viewDidLoad{[super viewDidLoad];self.title=@"图片下载";self.rows=@[];self.tasks=@[];self.cookies=nil;self.ua=@"";self.thumbs=[NSCache new];self.thumbs.countLimit=80;self.loading=[NSMutableSet set];self.thumbJobs=[NSMutableArray array];self.selectedURLs=[NSMutableSet set];self.submitting=[NSMutableSet set];self.tableView.rowHeight=84;self.tableView.allowsMultipleSelection=YES;self.navigationItem.leftBarButtonItem=[[UIBarButtonItem alloc] initWithBarButtonSystemItem:UIBarButtonSystemItemDone target:self action:@selector(close)];self.navigationItem.rightBarButtonItem=[[UIBarButtonItem alloc] initWithBarButtonSystemItem:UIBarButtonSystemItemRefresh target:self action:@selector(refresh)];self.downloadButton=[[UIBarButtonItem alloc] initWithTitle:@"下载选中" style:UIBarButtonItemStyleDone target:self action:@selector(downloadSelected)];self.toolbarItems=@[[[UIBarButtonItem alloc] initWithBarButtonSystemItem:UIBarButtonSystemItemFlexibleSpace target:nil action:nil],self.downloadButton];self.navigationController.toolbarHidden=NO;[[NSNotificationCenter defaultCenter] addObserver:self selector:@selector(mediaChanged:) name:@"PVXMediaChanged" object:nil];WKWebView *w=PVXCurrentWebView();[w.configuration.websiteDataStore.httpCookieStore getAllCookies:^(NSArray *cookies){self.cookies=cookies;[self.tableView reloadData];}];[w evaluateJavaScript:@"navigator.userAgent" completionHandler:^(id v,NSError *e){if([v isKindOfClass:NSString.class])self.ua=v;}];[self refresh];}
- (void)viewWillAppear:(BOOL)animated{[super viewWillAppear:animated];__weak typeof(self)weak=self;self.timer=[NSTimer scheduledTimerWithTimeInterval:2 repeats:YES block:^(NSTimer *t){[weak reloadTasks];}];[self reloadTasks];}
- (void)viewDidDisappear:(BOOL)animated{[super viewDidDisappear:animated];[self.timer invalidate];self.timer=nil;}
- (void)dealloc{[[NSNotificationCenter defaultCenter] removeObserver:self];[_timer invalidate];for(PVXThumbnail *j in _thumbJobs)[j.session invalidateAndCancel];}
- (void)close{[self dismissViewControllerAnimated:YES completion:nil];}
- (void)refresh{[[PVXMediaBridge shared] refresh];self.rows=[[PVXMediaBridge shared] images];[self.tableView reloadData];[self updateButton];}
- (void)mediaChanged:(NSNotification*)n{if(n.object!=PVXCurrentWebView())return;self.rows=[[PVXMediaBridge shared] images];[self.tableView reloadData];[self updateButton];}
- (void)updateButton{self.title=[NSString stringWithFormat:@"图片 · %lu",(unsigned long)self.rows.count];self.downloadButton.title=[NSString stringWithFormat:@"下载选中 (%lu)",(unsigned long)self.selectedURLs.count];self.downloadButton.enabled=self.selectedURLs.count>0;}
- (void)reloadTasks{NSString *dir=[PVXStateRoot() stringByAppendingPathComponent:@"image-tasks"];dispatch_async(dispatch_get_global_queue(QOS_CLASS_UTILITY,0),^{NSMutableArray *rows=[NSMutableArray array];NSArray *names=[NSFileManager.defaultManager contentsOfDirectoryAtPath:dir error:nil];for(NSString *name in names){if(![name.pathExtension isEqual:@"plist"]||![[NSUUID alloc] initWithUUIDString:name.stringByDeletingPathExtension])continue;NSString *path=[dir stringByAppendingPathComponent:name];NSDictionary *attrs=[NSFileManager.defaultManager attributesOfItemAtPath:path error:nil];if([attrs[NSFileSize] unsignedLongLongValue]>2*1024*1024)continue;NSDictionary *v=[NSDictionary dictionaryWithContentsOfFile:path];if([v isKindOfClass:NSDictionary.class])[rows addObject:v];if(rows.count>=500)break;}[rows sortUsingComparator:^NSComparisonResult(id a,id b){return [b[@"created"] compare:a[@"created"]];}];dispatch_async(dispatch_get_main_queue(),^{self.tasks=rows;[self.tableView reloadSections:[NSIndexSet indexSetWithIndex:1] withRowAnimation:UITableViewRowAnimationNone];});});}
- (NSInteger)numberOfSectionsInTableView:(UITableView*)table{return 2;}
- (NSInteger)tableView:(UITableView*)table numberOfRowsInSection:(NSInteger)section{return section==0?self.rows.count:self.tasks.count;}
- (NSString*)tableView:(UITableView*)table titleForHeaderInSection:(NSInteger)section{return section==0?@"当前网页图片 · 点选后下载原文件":@"图片下载任务";}
- (NSString*)tableView:(UITableView*)table titleForFooterInSection:(NSInteger)section{return section==0?@"支持当前页面及 iframe、已创建的开放 Shadow DOM 中的图片。小于 48×48 的已知小图已过滤；点击刷新可检测新加载图片。下载保留服务器提供的图片原始格式。":@"队列由独立后台服务执行，关闭此面板后继续下载。图片与原视频任务分开管理。";}
- (UITableViewCell*)tableView:(UITableView*)table cellForRowAtIndexPath:(NSIndexPath*)path{UITableViewCell *cell=[table dequeueReusableCellWithIdentifier:@"image"];if(!cell)cell=[[UITableViewCell alloc] initWithStyle:UITableViewCellStyleSubtitle reuseIdentifier:@"image"];cell.textLabel.numberOfLines=1;cell.detailTextLabel.numberOfLines=2;cell.imageView.image=[UIImage systemImageNamed:path.section==0?@"photo":@"arrow.down.circle"];cell.imageView.contentMode=UIViewContentModeScaleAspectFit;cell.accessoryType=UITableViewCellAccessoryNone;NSDictionary *row=path.section==0?self.rows[path.row]:self.tasks[path.row];cell.textLabel.text=PVXString(row[@"title"],180)?row[@"title"]:@"图片";NSString *url=row[@"url"];if(path.section==0){cell.detailTextLabel.text=[NSString stringWithFormat:@"%@ × %@ · %@",row[@"width"],row[@"height"],[NSURL URLWithString:url].host?:@""];cell.accessoryType=[self.selectedURLs containsObject:url]?UITableViewCellAccessoryCheckmark:UITableViewCellAccessoryNone;UIImage *cached=[self.thumbs objectForKey:url];if(cached){cell.imageView.image=cached;}else if(self.cookies&&self.thumbJobs.count<3&&![self.loading containsObject:url]){[self.loading addObject:url];__weak typeof(self)weak=self;__block __weak PVXThumbnail *weakJob;PVXThumbnail *job=[[PVXThumbnail alloc] initWithURL:PVXImageURL(url) cookies:self.cookies referer:row[@"page"]?:@"" ua:self.ua?:@"" done:^(UIImage *image){typeof(self)self=weak;if(!self)return;if(image)[self.thumbs setObject:image forKey:url];[self.thumbJobs removeObject:weakJob];[self.tableView reloadData];}];weakJob=job;[self.thumbJobs addObject:job];}}else{NSDictionary *states=@{@"queued":@"等待下载",@"downloading":@"下载中",@"saving":@"保存相册中",@"saved":@"已保存相册",@"failed":@"失败",@"uncertain":@"相册结果待确认"};NSString *state=states[row[@"state"]]?:row[@"state"]?:@"";NSString *error=PVXString(row[@"error"],2000)?row[@"error"]:@"";cell.detailTextLabel.text=error.length?[NSString stringWithFormat:@"%@ · %@",state,error]:state;if([row[@"state"] isEqual:@"saved"])cell.accessoryType=UITableViewCellAccessoryCheckmark;}return cell;}
- (void)tableView:(UITableView*)table didSelectRowAtIndexPath:(NSIndexPath*)path{[table deselectRowAtIndexPath:path animated:YES];if(path.section!=0){NSDictionary *t=self.tasks[path.row];NSString *error=PVXString(t[@"error"],2000)?t[@"error"]:@"";if(error.length)PVXAlert(@"图片任务",error);return;}NSString *url=self.rows[path.row][@"url"];if([self.selectedURLs containsObject:url])[self.selectedURLs removeObject:url];else[self.selectedURLs addObject:url];[table reloadRowsAtIndexPaths:@[path] withRowAnimation:UITableViewRowAnimationNone];[self updateButton];}
- (void)downloadSelected{WKWebView *w=PVXCurrentWebView();if(!w){PVXAlert(@"图片下载",@"原网页已关闭。");return;}NSArray *selected=[self.rows filteredArrayUsingPredicate:[NSPredicate predicateWithBlock:^BOOL(NSDictionary *r,NSDictionary *bindings){return [self.selectedURLs containsObject:r[@"url"]]&&![self.submitting containsObject:r[@"url"]];}]];if(!selected.count)return;for(NSDictionary *r in selected)[self.submitting addObject:r[@"url"]];NSString *owner=w.URL.absoluteString?:@"";__weak WKWebView *weakWeb=w;[w.configuration.websiteDataStore.httpCookieStore getAllCookies:^(NSArray *cookies){[weakWeb evaluateJavaScript:@"navigator.userAgent" completionHandler:^(id value,NSError *jsError){if(!weakWeb||![weakWeb.URL.absoluteString isEqual:owner]){for(NSDictionary *r in selected)[self.submitting removeObject:r[@"url"]];PVXAlert(@"图片下载",@"页面已切换，请重新检测后下载。");return;}NSString *ua=[value isKindOfClass:NSString.class]?value:self.ua?:@"";NSUInteger count=0;NSString *failure=nil;for(NSDictionary *row in selected){NSURL *url=PVXImageURL(row[@"url"]);if(!url)continue;NSMutableArray *props=[NSMutableArray array];for(NSHTTPCookie *cookie in PVXMatching(cookies,url))[props addObject:PVXCookieRecord(cookie)];NSDictionary *h=PVXHeaders(@[],url,row[@"page"]?:owner,ua);NSDictionary *request=@{@"id":NSUUID.UUID.UUIDString,@"kind":@"image",@"created":@(NSDate.date.timeIntervalSince1970),@"url":url.absoluteString,@"title":row[@"title"]?:@"图片",@"page":row[@"page"]?:owner,@"headers":h,@"cookies":props};NSError *e=nil;if(PVXWriteRequest(request,&e)){count++;[self.selectedURLs removeObject:row[@"url"]];}else failure=e.localizedDescription?:@"无法写入图片任务目录，请检查 libSandy 权限及插件安装。";[self.submitting removeObject:row[@"url"]];}[self updateButton];[self.tableView reloadData];PVXAlert(count?@"已加入图片下载":@"图片任务提交失败",failure?:[NSString stringWithFormat:@"%lu 张图片已加入后台队列，保存进度显示在下方任务列表。",(unsigned long)count]);}];}];}
@end
void PVXShowImages(void){dispatch_async(dispatch_get_main_queue(),^{UIViewController *p=PVXPresenter();if(!p)return;if([p isKindOfClass:PVXImageGallery.class])return;PVXImageGallery *g=[PVXImageGallery new];UINavigationController *nav=[[UINavigationController alloc] initWithRootViewController:g];nav.modalPresentationStyle=UIModalPresentationPageSheet;if(@available(iOS 15.0,*)){nav.sheetPresentationController.detents=@[UISheetPresentationControllerDetent.largeDetent];nav.sheetPresentationController.prefersGrabberVisible=YES;}[p presentViewController:nav animated:YES completion:nil];});}
static void(*PVXOrigPrepare)(id,SEL,id),(*PVXOrigTrack)(id,SEL,id),(*PVXOrigPanelLoad)(id,SEL);
static void PVXPrepare(id self,SEL cmd,id config){PVXOrigPrepare(self,cmd,config);[[PVXMediaBridge shared] configure:config];}
static void PVXTrack(id self,SEL cmd,id web){PVXOrigTrack(self,cmd,web);if([web isKindOfClass:WKWebView.class])[[PVXMediaBridge shared] configure:((WKWebView*)web).configuration];}
static void PVXPanelLoad(id self,SEL cmd){PVXOrigPanelLoad(self,cmd);UITableView *table=PVXGet(self,@"table");if(![table isKindOfClass:UITableView.class]||objc_getAssociatedObject(table,&PVXGalleryKey))return;UIButton *button=[UIButton buttonWithType:UIButtonTypeSystem];button.frame=CGRectMake(0,0,table.bounds.size.width,46);button.autoresizingMask=UIViewAutoresizingFlexibleWidth;[button setTitle:@"  检测并下载网页图片" forState:UIControlStateNormal];[button setImage:[UIImage systemImageNamed:@"photo.on.rectangle.angled"] forState:UIControlStateNormal];[button addAction:[UIAction actionWithHandler:^(__kindof UIAction *action){PVXShowImages();}] forControlEvents:UIControlEventTouchUpInside];table.tableHeaderView=button;objc_setAssociatedObject(table,&PVXGalleryKey,button,OBJC_ASSOCIATION_RETAIN_NONATOMIC);}
static BOOL PVXTypeMethod(Class c,SEL s,unsigned count){Method m=class_getInstanceMethod(c,s);if(!m||method_getNumberOfArguments(m)!=count)return NO;char *ret=method_copyReturnType(m);BOOL ok=ret&&ret[0]=='v';free(ret);if(count>2){char *arg=method_copyArgumentType(m,2);ok=ok&&arg&&arg[0]=='@';free(arg);}return ok;}
void PVXInstallImages(void){Class c=NSClassFromString(@"PVBrowser"),p=NSClassFromString(@"PVPanel");SEL prepare=NSSelectorFromString(@"prepareConfiguration:"),track=NSSelectorFromString(@"track:"),load=@selector(viewDidLoad);if(PVXTypeMethod(c,prepare,3))PVXHook(c,prepare,(IMP)PVXPrepare,(IMP*)&PVXOrigPrepare);if(PVXTypeMethod(c,track,3))PVXHook(c,track,(IMP)PVXTrack,(IMP*)&PVXOrigTrack);if(PVXTypeMethod(p,load,2))PVXHook(p,load,(IMP)PVXPanelLoad,(IMP*)&PVXOrigPanelLoad);id panel=PVXGet(PVXBrowser(),@"panel");if([panel isKindOfClass:UIViewController.class]&&[panel isViewLoaded]){UITableView *t=PVXGet(panel,@"table");if(t&&!objc_getAssociatedObject(t,&PVXGalleryKey))PVXLog(@"existing panel will acquire image entry after Safari restart");}WKWebView *w=PVXCurrentWebView();if(w){[[PVXMediaBridge shared] configure:w.configuration];[[PVXMediaBridge shared] refresh];}}
